package org.circus.core;
import java.awt.event.KeyEvent;import java.awt.image.BufferedImage;import java.io.*;import java.nio.file.*;import java.util.*;import javax.imageio.ImageIO;
/** Original six ed_* MES scripts and actual integer-alpha desktop output. */
public final class Dc2CharacterEndingAudit {
    private static int checks;private static long compared;
    private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    private static PcHost host(DesktopLegacy e){return(PcHost)e.host();}
    private static Dc2CharacterEnding ending(DesktopLegacy e){return host(e).dc2CharacterEnding;}
    private static int[] pixels(BufferedImage b){return b.getRGB(0,0,800,600,null,0,800);}
    private static String hash(int[] a){byte[] b=new byte[a.length*3];for(int n=0;n<a.length;n++)for(int k=0;k<3;k++)b[n*3+k]=(byte)(a[n]>>>(8*k));return Binary.sha256(b);}
    private static int[] expected(CircusResources data,List<Dc2CharacterEnding.Layer> layers)throws IOException {
        int[] result=new int[800*600];Arrays.fill(result,0xff000000);
        for(Dc2CharacterEnding.Layer layer:layers){Crx.Image source=data.image(layer.resource);check(source.bpp==24&&source.width==800&&source.height==600,"native character-ending source geometry "+layer.resource);for(int y=0;y<600;y++)for(int x=0;x<800;x++){int at=y*source.stride+x*3,n=y*800+x,b=source.pixels[at]&255,g=source.pixels[at+1]&255,r=source.pixels[at+2]&255;if(layer.opaque)result[n]=0xff000000|r<<16|g<<8|b;else if(!(r==255&&g==0&&b==255)){int old=result[n],a=layer.alpha,inv=16-a;result[n]=0xff000000|(((old>>>16&255)*inv+r*a)/16)<<16|(((old>>>8&255)*inv+g*a)/16)<<8|((old&255)*inv+b*a)/16;}}}
        return result;
    }
    private static Map<String,Object> frame(DesktopLegacy e,CircusResources data,Path out,String name)throws IOException {BufferedImage image=e.render();int[] actual=pixels(image),manual=expected(data,ending(e).frame());check(Arrays.equals(actual,manual),"exact native integer-alpha BGR oracle "+name);compared+=actual.length;ImageIO.write(image,"png",out.resolve(name+".png").toFile());image.flush();return Json.obj("name",name,"draw_index",ending(e).drawIndex,"draw_alpha",ending(e).drawAlpha,"draw_white_alpha",ending(e).drawWhiteAlpha,"sha256",hash(actual));}
    private static DesktopLegacy script(CircusResources data,TextCodec codec,String actor,int variant)throws Exception {DesktopLegacy e=new DesktopLegacy(data,codec,true);e.session.vm=new MesVm(data.scripts(),e.host(),"ed_"+actor);check(e.vm().run(1000)==MesVm.Status.WAIT_HOST&&ending(e).active&&ending(e).variant==variant,"original ed_"+actor+" performs10/checkpoint/11 modal wait");check(e.vm().variables.read(100,ending(e).clearIndex())==0,"fixture starts before first role clear");return e;}
    public static void main(String[] args)throws Exception {
        if(args.length!=2)throw new IOException("Require readonly_DC2_GAME owned_OUTPUT");Path game=Paths.get(args[0]).toRealPath(),out=DesktopRouteAudit.outputOutsideGame(game,args[1]);System.setProperty("dc.saveRoot",out.resolve("state").toString());System.setProperty("dc.cacheRoot",out.resolve("cache").toString());GameResources files=new GameResources(new LocalGameStorage(game),"dc2.exe");CircusResources data=new CircusResources(files,Profiles.get("dc2-3363"));TextCodec codec=GameText.detect(files,data.profile);
        String[] actors={"otm","yme","nnk","mnt","anz","kko"},epilogue={"ind_0401_a1_otm","ind_0401_a1_yme","ind_ep_nnk","mnt_2058_a1_mnt","anz_0216_b1_anz","ind_ep_kko"};List<Object> assets=new ArrayList<>(),frames=new ArrayList<>(),routes=new ArrayList<>();Set<String> seen=new HashSet<>();
        for(int variant=0;variant<6;variant++){Dc2CharacterEnding c=new Dc2CharacterEnding();c.prepare(variant,new int[24]);List<String> names=new ArrayList<>();for(int page=0;page<=c.count();page++)names.add(c.image(page));names.add("BG/white");for(String name:names)if(seen.add(name)){Crx.Image image=data.image(name);check(image.width==800&&image.height==600&&image.bpp==24,"actual full-screen original character-ending asset "+name);assets.add(Json.obj("resource",name,"x",image.x,"y",image.y,"width",image.width,"height",image.height,"bpp",image.bpp,"decoded_sha256",Binary.sha256(image.pixels)));}}
        check(assets.size()==124,"all122 distinct character images plus shared black/white decode");
        for(int variant=0;variant<6;variant++){
            DesktopLegacy e=script(data,codec,actors[variant],variant);Dc2CharacterEnding c=ending(e);e.modalKey(KeyEvent.VK_ENTER);e.vm().signalHost(e.ticket(),MesVm.HostSignal.ADVANCE);e.click(400,300,false);e.click(400,300,true);check(c.active&&!c.skipRequested(),"keyboard/ADVANCE and uncleared mouse cannot skip "+actors[variant]);e.vm().elapse(0);frames.add(frame(e,data,out,actors[variant]+"-entry-white15"));e.vm().elapse(49);check(c.whiteAlpha==15,"actual frontend stays between native50ms timer polls");e.vm().elapse(1);for(int n=0;n<14;n++)e.vm().elapse(50);
            int duration=e.vm().variables.read(6,50)*1000;e.vm().elapse(duration-999-c.elapsed());for(int n=0;n<8;n++)e.vm().elapse(50);check(c.drawAlpha==8&&c.drawWhiteAlpha==0,"actual script's first duration drives integer-alpha8 "+actors[variant]);frames.add(frame(e,data,out,actors[variant]+"-crossfade-alpha8"));
            byte[] saved=e.snapshot();BufferedImage b=e.render();int[] old=pixels(b);b.flush();e.vm().elapse(50);b=e.render();int[] future=pixels(b);b.flush();e.restore(saved);c=ending(e);b=e.render();check(Arrays.equals(old,pixels(b)),"actual role ending snapshot restores front "+actors[variant]);b.flush();e.vm().elapse(50);b=e.render();check(Arrays.equals(future,pixels(b)),"actual role ending snapshot restores next poll "+actors[variant]);b.flush();
            for(int n=0;n<1000&&c.active;n++){int page=c.index;long ms=e.vm().variables.read(6,50+page)*1000L;long beforeFade=ms-999-c.elapsed();if(beforeFade>0)e.vm().elapse(beforeFade);for(int poll=0;poll<20&&c.active&&c.index==page&&c.alpha<16;poll++)e.vm().elapse(50);if(c.active&&c.index==page)e.vm().elapse(Math.max(50,ms-c.elapsed()+1));}
            check(!c.active&&!c.prepared&&c.index>=c.count(),"all native pictures naturally complete "+actors[variant]);int pictureCount=c.count();frames.add(frame(e,data,out,actors[variant]+"-complete-front"));check(e.vm().variables.read(100,c.clearIndex())==0,"ending owner leaves route-clear write to later original epilogue "+actors[variant]);e.vm().run(3);check(e.vm().scriptName().equals(epilogue[variant])&&e.host().skipAllowed,"actual ed_"+actors[variant]+" returns to correct original epilogue");routes.add(Json.obj("variant",variant,"script","ed_"+actors[variant],"count",pictureCount,"epilogue",e.vm().scriptName(),"normal_completion",true));
        }
        DesktopLegacy skipped=script(data,codec,"anz",4);for(int n=0;n<16;n++)skipped.vm().elapse(50);skipped.vm().variables.write(100,5,1);skipped.click(400,300,true);check(ending(skipped).active&&ending(skipped).skipRequested(),"actual right mouse enqueues already-clear route flag");skipped.vm().elapse(0);check(ending(skipped).active,"zero-time refresh cannot bypass queued native timer");skipped.vm().elapse(50);check(!ending(skipped).active,"eligible role replay skip releases only on next poll");frames.add(frame(skipped,data,out,"already-clear-mouse-skip-front"));
        Files.write(out.resolve("result.json"),(Json.text(Json.obj("pass",true,"checks",checks,"assets",assets,"frames",frames,"routes",routes,"pixels_compared",compared,"heap_max_bytes",Runtime.getRuntime().maxMemory(),"target_sha256",Binary.sha256(files.read("dc2.exe",32*1024*1024)),"original_exe_executed",false,"original_game_directory_written",false,"scope","All six original ed_* scripts via system10/checkpoint/11,124 actual image assets, manual exact BGR/16 keyed blend oracle, session future pixels, natural final front and original epilogue transfer. Direct ed_* entry and isolated100:5=1 replay-skip fixture are not a title-to-ending route policy or running-original screenshot comparison."))+"\n").getBytes("UTF-8"));System.out.println("Dc2CharacterEndingAudit PASS "+checks+"; pixels="+compared);
    }
}
